"""Hindi narrations for all 100 OPSC OCS questions."""

# Format: q_no: (narration_question, narration_answer)
HINDI_NARRATIONS = {
    1: ("प्रश्न 1. लेखकों को उनकी पुस्तकों से मिलाइए। A L Basham, Donald E Smith, Rudolph and Rudolph, और W H Morris Jones.",
        "सही उत्तर है विकल्प D. A L Basham ने The Wonder That Was India लिखी। Donald E Smith ने India as a secular state लिखी। Rudolph and Rudolph ने In pursuit of Lakshmi लिखी। और W H Morris Jones ने Government and politics of India लिखी।"),
    2: ("प्रश्न 2. 15वें वित्त आयोग ने स्वास्थ्य अनुदान में किस पर ध्यान देने की सिफारिश की?",
        "सही उत्तर है विकल्प D. शहरी और ग्रामीण स्वास्थ्य अवसंरचना और प्राथमिक स्वास्थ्य सेवा को मजबूत करना। 15वें वित्त आयोग ने COVID-19 के बाद जमीनी स्तर पर स्वास्थ्य क्षमता निर्माण पर जोर दिया।"),
    3: ("प्रश्न 3. चोल नौसेना किस क्षेत्र के विरुद्ध अपने अभियान के लिए प्रसिद्ध थी?",
        "सही उत्तर है विकल्प C. इंडोनेशिया और श्रीलंका। राजेंद्र चोल प्रथम ने श्रीविजय साम्राज्य और श्रीलंका के विरुद्ध नौसैनिक अभियान चलाया। चोल नौसेना प्राचीन भारत की सबसे शक्तिशाली नौसेनाओं में से एक थी।"),
    4: ("प्रश्न 4. PM गति शक्ति राष्ट्रीय लॉजिस्टिक्स नीति का लक्ष्य क्या है?",
        "सही उत्तर है विकल्प B. सड़क, रेल, बंदरगाह और हवाई अड्डा अवसंरचना को तेज माल ढुलाई के लिए एकीकृत करना। PM गति शक्ति अक्टूबर 2021 में शुरू हुई 100 लाख करोड़ रुपये की मास्टर प्लान है।"),
    5: ("प्रश्न 5. भारत की LT-LEDS रणनीति NAPCC से कैसे अलग है?",
        "सही उत्तर है विकल्प B. यह क्षेत्र-विशिष्ट गहन डीकार्बोनाइजेशन रोडमैप प्रदान करती है। भारत ने COP27 में 2070 तक नेट-ज़ीरो लक्ष्य के लिए ऊर्जा, उद्योग और परिवहन क्षेत्रों का विस्तृत मार्ग प्रस्तुत किया।"),
    6: ("प्रश्न 6. मस्टर्ड गैस रासायनिक रूप से क्या है?",
        "सही उत्तर है विकल्प C. 2,2 prime dichlorodiethylsulfide. मस्टर्ड गैस एक रासायनिक हथियार है जो प्रथम विश्व युद्ध में इस्तेमाल हुआ। 1993 के रासायनिक हथियार कन्वेंशन के तहत इसे प्रतिबंधित किया गया।"),
    7: ("प्रश्न 7. बस्ती भूगोल के बारे में कौन से कथन सही हैं?",
        "सही उत्तर है विकल्प B. कथन 1, 3 और 4 सही हैं। कथन 2 गलत है क्योंकि घनी आबादी वाले चावल उगाने वाले क्षेत्रों में सघन बस्तियां होती हैं, न कि अलग-थलग फार्मस्टेड।"),
    8: ("प्रश्न 8. द्वितीय विश्व युद्ध के बाद वैश्विक आर्थिक शासन की नींव किन संस्थाओं ने रखी?",
        "सही उत्तर है विकल्प A. IMF, विश्व बैंक और GATT. ये तीन स्तंभ ब्रेटन वुड्स प्रणाली के तहत स्थापित हुए। IMF मौद्रिक स्थिरता, विश्व बैंक विकास और GATT, अब WTO, अंतरराष्ट्रीय व्यापार के नियम बनाता है।"),
    9: ("प्रश्न 9. भारत में मुद्रास्फीति के बारे में कौन से कथन सही हैं?",
        "सही उत्तर है विकल्प D. सभी कथन सही हैं। RBI मुद्रास्फीति लक्ष्यीकरण के लिए CPI का उपयोग करता है। कोर मुद्रास्फीति में खाद्य और ईंधन शामिल नहीं। आपूर्ति पक्ष के कारक कीमतों को प्रभावित करते हैं। और हेडलाइन मुद्रास्फीति में सभी घटक शामिल हैं।"),
    10: ("प्रश्न 10. 1976 में आपातकाल के बाद मौलिक कर्तव्यों की समिति की अध्यक्षता किसने की?",
         "सही उत्तर है विकल्प C. सरदार स्वर्ण सिंह। 1976 की सरदार स्वर्ण सिंह समिति ने संविधान में मौलिक कर्तव्य जोड़ने की सिफारिश की। 42वें संशोधन ने भाग 4A में अनुच्छेद 51A के तहत 10 मौलिक कर्तव्य जोड़े।"),
    11: ("प्रश्न 11. इलेक्ट्रॉन का तरंग स्वभाव किससे सिद्ध होता है?",
         "सही उत्तर है विकल्प D. क्रिस्टलीय ठोस से इलेक्ट्रॉन का विवर्तन प्रतिरूप। 1927 के डेविसन-जर्मर प्रयोग ने निकेल क्रिस्टल से इलेक्ट्रॉन विवर्तन दिखाकर डी ब्रॉग्ली के तरंग-कण द्वैत सिद्धांत की पुष्टि की।"),
    12: ("प्रश्न 12. राष्ट्रवादी महिलाओं को उनकी गतिविधियों से मिलाइए।",
         "सही उत्तर है विकल्प B, क्रम 3, 4, 1, 2. सरोजिनी नायडू ने धरसाना में नमक सत्याग्रह का नेतृत्व किया। उषा मेहता ने भारत छोड़ो आंदोलन में गुप्त रेडियो चलाया। अरुणा आसफ अली भूमिगत नेता थीं। और डॉ. लक्ष्मी स्वामीनाथन INA में शामिल हुईं।"),
    13: ("प्रश्न 13. 2025 का कंबोडिया-थाईलैंड सीमा संघर्ष मुख्य रूप से किस कारण हुआ?",
         "सही उत्तर है विकल्प B. प्रिया विहार मंदिर और आसपास के क्षेत्र पर ऐतिहासिक विवाद। ICJ ने 1962 में फैसला दिया कि मंदिर कंबोडिया का है, लेकिन आसपास का क्षेत्र विवादित रहा। यह UNESCO विश्व धरोहर स्थल है।"),
    14: ("प्रश्न 14. भारतीय संविधान को seamless web किसने कहा?",
         "सही उत्तर है विकल्प A. ग्रैनविल ऑस्टिन। उन्होंने 1966 में अपनी पुस्तक The Indian Constitution: Cornerstone of a Nation में संविधान को seamless web बताया, जहां सामाजिक क्रांति, लोकतांत्रिक सरकार और राष्ट्रीय एकता अविभाज्य रूप से जुड़े हैं।"),
    15: ("प्रश्न 15. सामाजिक कल्याण नीतियों और उनके वर्ष का सही मिलान कौन सा है?",
         "सही उत्तर है विकल्प A. सभी चारों सही हैं। PM POSHAN 2021 में, शिक्षा का अधिकार 2009 में, आयुष्मान भारत सितंबर 2018 में, और PM आवास योजना जून 2015 में शुरू हुई।"),
    16: ("प्रश्न 16. भारत में शहरीकरण की चुनौतियों के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प C. कथन 1, 2 और 4 सही हैं। कथन 3 गलत है क्योंकि शहरी क्षेत्रों में बेरोजगारी ग्रामीण क्षेत्रों से कम होती है, अधिक नहीं।"),
    17: ("प्रश्न 17. लिंगायत संप्रदाय के संस्थापक कौन थे?",
         "सही उत्तर है विकल्प B. बसव, जिन्हें बसवेश्वर भी कहते हैं। उन्होंने 12वीं शताब्दी में कर्नाटक में लिंगायत आंदोलन की स्थापना की। उन्होंने जाति व्यवस्था का विरोध किया और अनुभव मंटप की स्थापना की।"),
    18: ("प्रश्न 18. तारकुंडे रिपोर्ट किससे संबंधित है?",
         "सही उत्तर है विकल्प A. चुनाव सुधार। न्यायमूर्ति V M तारकुंडे की 1974-75 की समिति ने चुनावों के राज्य वित्तपोषण और मतदान की आयु 21 से 18 वर्ष करने की सिफारिश की।"),
    19: ("प्रश्न 19. CAMPA कोष किन गतिविधियों के लिए प्राथमिकता पर है?",
         "सही उत्तर है विकल्प C. प्रतिपूरक वनीकरण और पारिस्थितिक पुनर्स्थापना। CAMPA अधिनियम 2016 उन कोषों का प्रबंधन करता है जो वन भूमि को गैर-वन उपयोग के लिए हटाने पर एकत्र किए जाते हैं।"),
    20: ("प्रश्न 20. द्वैध शासन प्रणाली किस उपाय से शुरू की गई?",
         "सही उत्तर है विकल्प C. भारत सरकार अधिनियम 1919, जिसे मॉन्टेग्यू-चेम्सफोर्ड सुधार भी कहते हैं। इसमें प्रांतीय विषयों को हस्तांतरित और आरक्षित में बांटा गया।"),
    21: ("प्रश्न 21. निम्न में से कौन सी अनअपचायी शर्करा है?",
         "सही उत्तर है विकल्प C. सुक्रोज़। सुक्रोज़ में कोई मुक्त एनोमेरिक कार्बन नहीं होता, इसलिए यह अनअपचायी शर्करा है। ग्लूकोज़, फ्रक्टोज़ और माल्टोज़ अपचायी शर्करा हैं।"),
    22: ("प्रश्न 22. विश्व सांस्कृतिक क्षेत्रों के बारे में कौन से कथन गलत हैं?",
         "सही उत्तर है विकल्प C. केवल कथन 3 गलत है। इस्लामी क्षेत्र केवल अरब प्रायद्वीप तक सीमित नहीं है। यह उत्तरी अफ्रीका, मध्य एशिया, दक्षिण एशिया और दक्षिण-पूर्व एशिया तक फैला है।"),
    23: ("प्रश्न 23. ओडिशा की CM-KISAN योजना के बारे में कौन सा कथन गलत है?",
         "सही उत्तर है विकल्प A. केवल कथन 1 गलत है। CM-KISAN सभी किसानों के लिए है, केवल बड़े भूमिधारकों के लिए नहीं। यह एक प्रगतिशील और समावेशी योजना है।"),
    24: ("प्रश्न 24. निम्नलिखित समितियों को कालानुक्रमिक क्रम में व्यवस्थित करें।",
         "सही उत्तर है विकल्प D. क्रम है: DS कोठारी समिति 1964, राजा चेल्लैया समिति 1991, NN वोहरा समिति 1993, और राजिंदर सच्चर समिति 2005।"),
    25: ("प्रश्न 25. निम्न में से कौन रंजक नहीं है?",
         "सही उत्तर है विकल्प D. एंथ्रानिलिक एसिड। यह एक अमीनो एसिड व्युत्पन्न है जो दवा निर्माण में उपयोग होता है, रंजक नहीं। एलिज़रिन, फ्लोरेसिन और फिनोल्फ्थेलीन रंजक हैं।"),
    26: ("प्रश्न 26. IDCO के बारे में कौन सा कथन गलत है?",
         "सही उत्तर है विकल्प B. कथन 4 गलत है। IDCO के कार्यों में भूमि अधिग्रहण और भूमि बैंक बनाना शामिल है। IDCO 1981 में स्थापित ओडिशा में औद्योगिक अवसंरचना की नोडल एजेंसी है।"),
    27: ("प्रश्न 27. नियंत्रक एवं महालेखा परीक्षक के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. सभी चारों कथन सही हैं। CAG का कार्यालय 1919 के अधिनियम पर आधारित है। CAG अनुच्छेद 148 के तहत लेखा परीक्षा का निष्पक्ष प्रमुख है। CAG को सिद्ध दुर्व्यवहार पर हटाया जा सकता है। और कार्यकाल 6 वर्ष या 65 वर्ष की आयु तक है।"),
    28: ("प्रश्न 28. किस मुगल सम्राट के शासन में ओडिशा में मुहतसिब का पद स्थापित हुआ?",
         "सही उत्तर है विकल्प B. औरंगज़ेब। उन्होंने मुगल साम्राज्य में इस्लामी कानून लागू करने के लिए मुहतसिब नियुक्त किए। औरंगज़ेब अपनी कठोर धार्मिक नीतियों के लिए जाने जाते थे।"),
    29: ("प्रश्न 29. सभी ओडिया भाषी क्षेत्रों के एकीकरण की मांग करने वाले पहले नेता कौन थे?",
         "सही उत्तर है विकल्प A. मधुसूदन दास, जिन्हें उत्कल गौरव कहा जाता है। वे ओडिशा के Grand Old Man थे। ओडिशा 1 अप्रैल 1936 को एक अलग प्रांत बना।"),
    30: ("प्रश्न 30. अंतर-राज्य परिषद के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प A. केवल कथन 1 और 4 सही हैं। अंतर-राज्य परिषद अनुच्छेद 263 के तहत स्थापित है। सरकारिया आयोग ने इसकी सिफारिश की, पुंछी ने नहीं। और प्रधानमंत्री अध्यक्ष हैं, गृह मंत्री नहीं।"),
    31: ("प्रश्न 31. कौन सी जलवायु पहल विशेष रूप से हिमालयी हिमनद निगरानी का समर्थन करती है?",
         "सही उत्तर है विकल्प B. राष्ट्रीय हिमालयी पारिस्थितिकी तंत्र मिशन। यह NAPCC के 8 मिशनों में से एक है जो हिमालयी हिमनदों और जैव विविधता की निगरानी पर केंद्रित है।"),
    32: ("प्रश्न 32. वैश्विक औद्योगिक प्रतिरूप के बारे में कौन सा कथन गलत है?",
         "सही उत्तर है विकल्प D. केवल कथन 4 गलत है। कनाडा और ऑस्ट्रेलिया मुख्य रूप से संसाधन-आधारित उद्योगों के लिए जाने जाते हैं, भारी उद्योग के लिए नहीं।"),
    33: ("प्रश्न 33. 23 अप्रैल 1946 को ओडिशा में कांग्रेस मंत्रालय का पहला प्रमुख प्रशासनिक कदम क्या था?",
         "सही उत्तर है विकल्प A. जमींदारी बंदोबस्त का उन्मूलन। हरे कृष्ण महताब के नेतृत्व में कांग्रेस मंत्रालय ने यह ऐतिहासिक भूमि सुधार किया।"),
    34: ("प्रश्न 34. पैरेटो इष्टतमता की सबसे अच्छी परिभाषा क्या है?",
         "सही उत्तर है विकल्प B. ऐसी स्थिति जहां किसी को भी बेहतर नहीं बनाया जा सकता बिना किसी और को नुकसान पहुंचाए। इटली के अर्थशास्त्री विल्फ्रेडो पैरेटो के नाम पर, यह कल्याणकारी अर्थशास्त्र की प्रमुख अवधारणा है।"),
    35: ("प्रश्न 35. सुप्रीम कोर्ट के न्यायाधीश के महाभियोग के बारे में कौन से कथन गलत हैं?",
         "सही उत्तर है विकल्प C. कथन C और D गलत हैं। राष्ट्रपति न्यायाधीश को क्षमादान नहीं दे सकते, हटाने का अधिकार केवल संसद को है।"),
    36: ("प्रश्न 36. सतत विकास लक्ष्यों के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प A. कथन 1, 2 और 3 सही हैं। कथन 4 गलत है क्योंकि सतत उपभोग और उत्पादन SDG 12 के तहत है, SDG 14 नहीं। SDG 14 जलीय जीवन के बारे में है।"),
    37: ("प्रश्न 37. RTI अधिनियम की धारा 4 में सूचना प्रकाशित करने की समय सीमा कितने दिन है?",
         "सही उत्तर है विकल्प A. 120 दिन। RTI अधिनियम 2005 की धारा 4 के तहत प्रत्येक सार्वजनिक प्राधिकरण को अधिनियम के लागू होने के 120 दिनों के भीतर 17 श्रेणियों की जानकारी प्रकाशित करनी होती है।"),
    38: ("प्रश्न 38. भारत में रामसर स्थलों के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. तीनों कथन सही हैं। रामसर स्थल पारिस्थितिक महत्व के आधार पर घोषित होते हैं। चिलिका झील 1981 में भारत का पहला रामसर स्थल बना। और 2023 तक भारत में 75 से अधिक रामसर स्थल हैं।"),
    39: ("प्रश्न 39. परमादेश रिट किस उद्देश्य से जारी की जाती है?",
         "सही उत्तर है विकल्प C. किसी सार्वजनिक अधिकारी को सार्वजनिक कर्तव्य निभाने के लिए बाध्य करना। याद रखें: बंदी प्रत्यक्षीकरण अवैध हिरासत के लिए, प्रमाणित लेख मामले के स्थानांतरण के लिए, और अधिकार पृच्छा पद की वैधता जांचने के लिए है।"),
    40: ("प्रश्न 40. समुद्रयान मिशन के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प B. कथन 2 और 3 सही हैं। समुद्रयान MATSYA 6000 विकसित कर रहा है, एक स्वचालित मानवयुक्त पनडुब्बी जो 6000 मीटर गहराई तक जा सकती है। यह गहरे समुद्र मिशन का हिस्सा है।"),
    41: ("प्रश्न 41. भारत की जलीय कृषि नीतियों के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प A. कथन 1, 2 और 3 सही हैं। कथन 4 गलत है क्योंकि FAO की आचार संहिता स्वैच्छिक है, कानूनी रूप से बाध्यकारी नहीं।"),
    42: ("प्रश्न 42. POSH अधिनियम 2013 के तहत शिकायत की समय सीमा क्या है?",
         "सही उत्तर है विकल्प D. तीन महीने। पीड़ित महिला को घटना के 3 महीने के भीतर शिकायत दर्ज करनी होती है, जिसे 3 महीने और बढ़ाया जा सकता है।"),
    43: ("प्रश्न 43. भारत में स्थानिक प्रजातियों के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प A. कथन 1 और 2 सही हैं। कथन 3 गलत है क्योंकि स्थानिक प्रजातियां हमेशा गंभीर रूप से संकटग्रस्त नहीं होतीं। स्थानिकता और संरक्षण स्थिति अलग अवधारणाएं हैं।"),
    44: ("प्रश्न 44. UPSC का उल्लेख संविधान के किस भाग में है?",
         "सही उत्तर है विकल्प C. भाग 14, जो संघ और राज्यों के अधीन सेवाओं से संबंधित है, अनुच्छेद 315 से 323 तक।"),
    45: ("प्रश्न 45. भारत में परिसीमन के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. सभी चारों कथन सही हैं। परिसीमन निर्वाचन क्षेत्रों की सीमाएं फिर से तय करता है, इसके आदेशों को अदालत में चुनौती नहीं दी जा सकती, यह एक व्यक्ति एक मत के सिद्धांत को कायम रखता है।"),
    46: ("प्रश्न 46. किस ब्रिटिश गवर्नर जनरल ने ओडिशा को ब्रिटिश साम्राज्य में मिलाया?",
         "सही उत्तर है विकल्प C. लॉर्ड वेलेस्ली। उन्होंने 1803 में आंग्ल-मराठा युद्ध के बाद ओडिशा को ब्रिटिश साम्राज्य में मिलाया। देवगांव की संधि से भोंसले शासक ने कटक को अंग्रेजों को सौंप दिया।"),
    47: ("प्रश्न 47. 2024 के नोबेल पुरस्कार और विजेता का कौन सा मिलान गलत है?",
         "सही उत्तर है विकल्प A. नर्गेस मोहम्मदी ने 2023 में शांति का नोबेल जीता, 2024 में नहीं। 2024 का नोबेल शांति पुरस्कार निहोन हिडांक्यो को मिला, जो जापानी परमाणु बम पीड़ितों का संगठन है।"),
    48: ("प्रश्न 48. 97वें अकादमी पुरस्कारों में सर्वश्रेष्ठ कॉस्ट्यूम डिज़ाइन का ऑस्कर जीतने वाले पहले अश्वेत पुरुष कौन बने?",
         "सही उत्तर है विकल्प A. Paul Tazewell. उन्होंने Wicked फिल्म के लिए 2025 में 97वें अकादमी पुरस्कारों में यह ऑस्कर जीता।"),
    49: ("प्रश्न 49. प्राचीन ग्रंथों को कालानुक्रमिक क्रम में व्यवस्थित करें।",
         "सही उत्तर है विकल्प A. क्रम है: बृहदारण्यक उपनिषद 800 से 600 ईसा पूर्व, फिर मनुस्मृति, फिर अर्थशास्त्र, और अंत में मिलिंद पन्ह। ये कई शताब्दियों के भारतीय बौद्धिक परंपरा का प्रतिनिधित्व करते हैं।"),
    50: ("प्रश्न 50. भारत के राष्ट्रीय स्तर पर निर्धारित योगदान NDC के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. तीनों कथन सही हैं। भारत ने 2030 तक उत्सर्जन तीव्रता में 45 प्रतिशत कमी, 50 प्रतिशत गैर-जीवाश्म ईंधन क्षमता, और COP26 में पंचामृत प्रतिज्ञा पर आधारित लक्ष्य निर्धारित किए हैं।"),
    51: ("प्रश्न 51. अगस्त 2025 में भारत के नए उप राष्ट्रीय सुरक्षा सलाहकार कौन नियुक्त हुए?",
         "सही उत्तर है विकल्प B. TV रविचंद्रन। वे अगस्त 2025 में भारत के नए उप राष्ट्रीय सुरक्षा सलाहकार नियुक्त हुए।"),
    52: ("प्रश्न 52. संयुक्त राष्ट्र दिवसों को उनकी तारीखों से मिलाइए।",
         "सही उत्तर है विकल्प A. 3 मार्च विश्व वन्यजीव दिवस, 7 अप्रैल विश्व स्वास्थ्य दिवस, 3 मई विश्व प्रेस स्वतंत्रता दिवस, और 20 जून विश्व शरणार्थी दिवस है।"),
    53: ("प्रश्न 53. 38वें राष्ट्रीय खेलों की आधिकारिक थीम क्या थी?",
         "सही उत्तर है विकल्प C. ग्रीन गेम्स। उत्तराखंड में 2025 में आयोजित 38वें राष्ट्रीय खेलों ने पर्यावरणीय स्थिरता पर जोर देते हुए ग्रीन गेम्स थीम अपनाई।"),
    54: ("प्रश्न 54. ओडिशा पर औपनिवेशिक नीतियों के प्रभाव से मिलाइए।",
         "सही उत्तर है विकल्प A. स्थायी बंदोबस्त 1793 ने आर्थिक संकट बढ़ाया। ब्रिटिश पुनर्गठन ने ओडिया क्षेत्रों को विभिन्न प्रेसीडेंसियों में बांटा। बंगाली थोपने से ओडिया भाषाई पहचान आंदोलन शुरू हुआ।"),
    55: ("प्रश्न 55. भारतीय नदियों को उनकी सहायक नदियों से मिलाइए।",
         "सही उत्तर है विकल्प B. चंबल की सहायक नदी बनास, कावेरी की नोय्यल, कृष्णा की भीमा, और गोदावरी की मांजरा है।"),
    56: ("प्रश्न 56. ओडिशा की नदियों को उनकी सहायक नदियों से मिलाइए।",
         "सही उत्तर है विकल्प C. महानदी की सहायक नदी ओंग, ब्राह्मणी शंख और दक्षिण कोयल के संगम से बनती है, बैतरणी की देव, और सुवर्णरेखा की रारू है।"),
    57: ("प्रश्न 57. भारत में सोने के सिक्के सबसे पहले किसने जारी किए?",
         "सही उत्तर है विकल्प D. इंडो-ग्रीक। उन्होंने दूसरी शताब्दी ईसा पूर्व के आसपास भारत में पहली बार सोने के सिक्के जारी किए। कुषाणों ने बाद में प्रसिद्ध सोने के सिक्के जारी किए।"),
    58: ("प्रश्न 58. सामाजिक न्याय विभाग ने किस संगठन के साथ समझौता ज्ञापन पर हस्ताक्षर किए?",
         "सही उत्तर है विकल्प C. NALSA, राष्ट्रीय विधिक सेवा प्राधिकरण। यह समझौता वंचित समुदायों के लिए सामाजिक न्याय योजनाओं की जागरूकता बढ़ाने के लिए है।"),
    59: ("प्रश्न 59. सरकारी पहलों को उनके शुरू होने के वर्ष से मिलाइए।",
         "सही उत्तर है विकल्प A. आयुष्मान भारत 2018 में, राष्ट्रीय कौशल विकास मिशन 2015 में, MGNREGS 2006 में, और प्रधानमंत्री जन धन योजना 2014 में शुरू हुई।"),
    60: ("प्रश्न 60. राजपूत शासकों को उनके प्रमुख युद्धों से मिलाइए।",
         "सही उत्तर है विकल्प A. राणा सांगा ने 1527 में खानवा का युद्ध लड़ा। महाराणा प्रताप ने 1576 में हल्दीघाटी का युद्ध लड़ा। राव चंद्रसेन ने अकबर का विरोध किया। और राजा मान सिंह ने ओडिशा जीता।"),
    61: ("प्रश्न 61. भारतीय अर्थव्यवस्था के संरचनात्मक परिवर्तन के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. सभी कथन सही हैं। सेवा क्षेत्र GDP वृद्धि को चलाता है। Make in India 25 प्रतिशत विनिर्माण लक्ष्य रखता है। कृषि का GDP हिस्सा घटा लेकिन रोजगार हिस्सा महत्वपूर्ण है। और समय पूर्व विऔद्योगीकरण भारत के विकास पथ का सटीक वर्णन है।"),
    62: ("प्रश्न 62. किस अनुच्छेद में सुप्रीम कोर्ट का कानून सभी अदालतों पर बाध्यकारी है?",
         "सही उत्तर है विकल्प B. अनुच्छेद 141. यह कहता है कि सुप्रीम कोर्ट द्वारा घोषित कानून भारत की सभी अदालतों पर बाध्यकारी होगा। यह पूर्व-निर्णय का सिद्धांत स्थापित करता है।"),
    63: ("प्रश्न 63. G20 के बारे में कौन सा कथन गलत है?",
         "सही उत्तर है विकल्प D. चिली G20 का सदस्य नहीं है। G20 में 19 देश, यूरोपीय संघ और अफ्रीकी संघ शामिल हैं। चिली को अतिथि के रूप में आमंत्रित किया गया है लेकिन सदस्य नहीं है।"),
    64: ("प्रश्न 64. हिंदुस्तान सोशलिस्ट रिपब्लिकन एसोसिएशन की विचारधारा किससे प्रेरित थी?",
         "सही उत्तर है विकल्प D. आयरिश स्वतंत्रता संग्राम और सिन फेन आंदोलन। HSRA, जिसकी स्थापना 1928 में भगत सिंह और चंद्रशेखर आज़ाद ने की, ने ब्रिटिश उपनिवेशवाद के खिलाफ आयरिश प्रतिरोध मॉडल से प्रेरणा ली।"),
    65: ("प्रश्न 65. कौन सा मौलिक अधिकार केवल भारतीय नागरिकों के लिए है?",
         "सही उत्तर है विकल्प B. अनुच्छेद 19 के तहत भाषण और अभिव्यक्ति की स्वतंत्रता। अनुच्छेद 14, 20 और 21 विदेशियों सहित सभी व्यक्तियों के लिए उपलब्ध हैं, लेकिन अनुच्छेद 19 केवल नागरिकों के लिए है।"),
    66: ("प्रश्न 66. भूवैज्ञानिक संरचनाओं को उनके आर्थिक महत्व से मिलाइए।",
         "सही उत्तर है विकल्प C. शिवालिक पहाड़ियों में जीवाश्म समृद्ध तलछटी निक्षेप, दक्कन ट्रैप में काली कपास मिट्टी, सिंहभूम क्रेटन लौह अयस्क में समृद्ध, और छोटा नागपुर पठार कोयला, अभ्रक और यूरेनियम का भंडार है।"),
    67: ("प्रश्न 67. वैश्विक भुखमरी सूचकांक 2023 में भारत की रैंक क्या है?",
         "सही उत्तर है विकल्प C. 111. भारत 125 देशों में 111वें स्थान पर रहा, जिसे गंभीर श्रेणी में रखा गया। यह नेपाल, बांग्लादेश और श्रीलंका जैसे पड़ोसियों से पीछे है।"),
    68: ("प्रश्न 68. पारिस्थितिक पिरामिडों के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प C. कथन 1 और 3 सही हैं। कथन 2 गलत है। ऊर्जा के पिरामिड कभी उलटे नहीं होते, यह 10 प्रतिशत ऊर्जा स्थानांतरण नियम के कारण है।"),
    69: ("प्रश्न 69. भारत के महान्यायवादी के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प A. कथन 1, 2 और 3 सही हैं। कथन 4 गलत है क्योंकि अनुच्छेद 148 CAG से संबंधित है, महान्यायवादी से नहीं। महान्यायवादी का वेतन राष्ट्रपति द्वारा निर्धारित होता है।"),
    70: ("प्रश्न 70. चेनाब रेल पुल के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. कथन 2 और 4 सही हैं। चेनाब रेल पुल 359 मीटर पर विश्व का सबसे ऊंचा रेलवे आर्क पुल है और एफिल टॉवर से ऊंचा है। यह आर्क पुल है, केबल-स्टेड नहीं, और USBRL परियोजना का हिस्सा है।"),
    71: ("प्रश्न 71. संविधान की अनुसूचियों का कौन सा मिलान सही है?",
         "सही उत्तर है विकल्प B. 7वीं अनुसूची में संघ और राज्यों के बीच शक्तियों का विभाजन है, जिसमें संघ सूची, राज्य सूची और समवर्ती सूची शामिल हैं। 8वीं अनुसूची भाषाओं की है, 6वीं जनजातीय क्षेत्रों की।"),
    72: ("प्रश्न 72. IUCN वर्गीकरण में कौन सी श्रेणी वन्यजीव संरक्षण अधिनियम 1972 में सीधे मान्यता प्राप्त नहीं है?",
         "सही उत्तर है विकल्प C. स्थानिक यानी Endemic. स्थानिक एक भू-भौगोलिक शब्द है, IUCN खतरे की श्रेणी नहीं। IUCN श्रेणियों में गंभीर रूप से संकटग्रस्त, संवेदनशील और जंगल में विलुप्त शामिल हैं।"),
    73: ("प्रश्न 73. एसिटाइलसैलिसिलिक एसिड को क्या कहते हैं?",
         "सही उत्तर है विकल्प B. एस्पिरिन। एसिटाइलसैलिसिलिक एसिड एस्पिरिन का रासायनिक नाम है, जिसे 1897 में Bayer में Felix Hoffmann ने खोजा। यह दर्द निवारक और रक्त को पतला करने वाली दवा है।"),
    74: ("प्रश्न 74. ओडिशा की प्रमुख हस्तियों को उनकी गतिविधियों से मिलाइए।",
         "सही उत्तर है विकल्प B. मधुसूदन दास ने उत्कल सम्मिलनी की स्थापना की। बक्सी जगबंधु ने 1817 के पाइक विद्रोह का नेतृत्व किया। फकीर मोहन सेनापति आधुनिक ओडिया साहित्य के अग्रदूत थे। और कृष्ण चंद्र गजपति ने अलग प्रांत आंदोलन में महत्वपूर्ण भूमिका निभाई।"),
    75: ("प्रश्न 75. NISAR का पूर्ण रूप क्या है?",
         "सही उत्तर है विकल्प B. NASA ISRO Synthetic Aperture Radar. यह NASA और ISRO का संयुक्त पृथ्वी अवलोकन उपग्रह है जो 12 दिनों में पूरे ग्रह का मानचित्र बनाएगा।"),
    76: ("प्रश्न 76. भारत में सेवा क्षेत्र के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. सभी कथन सही हैं। सेवा क्षेत्र GDP का 55 प्रतिशत योगदान देता है। रोजगार हिस्सा कृषि से कम है। विकास को बिना रोजगार की वृद्धि कहा गया है। और IT क्षेत्र ने भारत को वैश्विक सेवा केंद्र बनाया है।"),
    77: ("प्रश्न 77. पूर्वी घाट ग्रैन्युलाइट पेटी के बारे में अभिकथन और कारण पर विचार करें।",
         "सही उत्तर है विकल्प A. अभिकथन और कारण दोनों सही हैं, और कारण अभिकथन की सही व्याख्या करता है। पूर्वी घाट की प्राचीन कायांतरित चट्टानों से बॉक्साइट, मैंगनीज, ग्रेफाइट और रत्नों का खनिजीकरण सीधे जुड़ा है।"),
    78: ("प्रश्न 78. दलित वर्ग के नेताओं को उनके संगठनों से मिलाइए।",
         "सही उत्तर है विकल्प B. MC राजा ने Depressed Classes Association बनाई। जगजीवन राम ने Depressed Classes League बनाई। BR अंबेडकर ने Depressed Classes Congress बनाई। और महात्मा गांधी ने 1932 में All India Harijan Sangh की स्थापना की।"),
    79: ("प्रश्न 79. शैलोद्भव वंश के गंजाम ताम्रपत्र किस पहलू की जानकारी देते हैं?",
         "सही उत्तर है विकल्प A. शैलोद्भव शासकों की वंशावली और क्षेत्रीय विस्तार। ताम्रपत्र अनुदान प्राचीन और मध्यकालीन भारत में राजवंशों, उनकी वंशावली और भूमि अनुदान की जानकारी का प्राथमिक स्रोत थे।"),
    80: ("प्रश्न 80. एशिया कप क्रिकेट के बारे में कौन सा कथन गलत है?",
         "सही उत्तर है विकल्प D. केवल कथन 4 गलत है। पहला एशिया कप 1984 में शारजाह, UAE में हुआ, कोलंबो श्रीलंका में नहीं।"),
    81: ("प्रश्न 81. हिमालय के उप-विभाजनों को उनकी विशेषताओं से मिलाइए।",
         "सही उत्तर है विकल्प C. ट्रांस-हिमालय में काराकोरम, लद्दाख और ज़ास्कर श्रेणियां हैं। महान हिमालय में एवरेस्ट और कंचनजंगा जैसी सबसे ऊंची चोटियां हैं।"),
    82: ("प्रश्न 82. राज्यसभा के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प B. कथन 1, 2 और 3 सही हैं। राज्यसभा एक स्थायी निकाय है जो कभी भंग नहीं होती। एक तिहाई सदस्य हर 2 वर्ष में सेवानिवृत्त होते हैं। उपराष्ट्रपति पदेन सभापति हैं। कथन 4 गलत है, राष्ट्रीय आपातकाल में भी राज्यसभा भंग नहीं होती।"),
    83: ("प्रश्न 83. तालीकोटा का युद्ध किसने लड़ा?",
         "सही उत्तर है विकल्प D. राम राय। 1565 का तालीकोटा युद्ध, जिसे राक्षसी-तांगड़ी का युद्ध भी कहते हैं, विजयनगर साम्राज्य और दक्कन सल्तनतों की संयुक्त सेना के बीच हुआ। राम राय की हार से विजयनगर साम्राज्य का पतन शुरू हुआ।"),
    84: ("प्रश्न 84. राष्ट्रीय आपदा प्रबंधन प्राधिकरण NDMA किसके अधीन कार्य करता है?",
         "सही उत्तर है विकल्प D. प्रधानमंत्री कार्यालय। प्रधानमंत्री NDMA के पदेन अध्यक्ष हैं। इसकी स्थापना आपदा प्रबंधन अधिनियम 2005 के तहत हुई।"),
    85: ("प्रश्न 85. भारत की पहली OECM मान्यता किस कारण से मिली?",
         "सही उत्तर है विकल्प B. स्थानिक जीवों वाले पवित्र वन। OECM पारंपरिक संरक्षित क्षेत्रों के बाहर जैव विविधता संरक्षण को मान्यता देते हैं। भारत के पवित्र वनों ने सदियों से सांस्कृतिक प्रथाओं के माध्यम से जैव विविधता की रक्षा की है।"),
    86: ("प्रश्न 86. उदयगिरि पहाड़ियों पर जैन मठों का निर्माण किसने करवाया?",
         "सही उत्तर है विकल्प C. राजा खारवेल। कलिंग के ईसा पूर्व प्रथम शताब्दी के राजा खारवेल ने ये चट्टानों को काटकर बनाए गए जैन मठ बनवाए। हाथीगुम्फा शिलालेख में उनके विजय अभियानों का वर्णन है।"),
    87: ("प्रश्न 87. उष्णकटिबंधीय सदाबहार वनों के बारे में कौन से कथन गलत हैं?",
         "सही उत्तर है विकल्प B. कथन 1 और 2 गलत हैं। ये वन पश्चिमी घाट, पूर्वोत्तर भारत और अंडमान निकोबार में पाए जाते हैं, केवल पूर्वी घाट में नहीं। और सदाबहार होने के कारण ये एक साथ सभी पत्तियां नहीं गिराते।"),
    88: ("प्रश्न 88. सूर्य हेलियोफिजिक्स फाउंडेशन मॉडल क्या है?",
         "सही उत्तर है विकल्प B. सौर गतिविधि का पूर्वानुमान लगाने का AI मॉडल। यह डीप लर्निंग का उपयोग करके सौर ज्वालाओं और अंतरिक्ष मौसम की घटनाओं की भविष्यवाणी करता है जो पृथ्वी की प्रौद्योगिकी प्रणालियों को प्रभावित कर सकती हैं।"),
    89: ("प्रश्न 89. राजा राम मोहन राय के धार्मिक संगठनों को कालानुक्रमिक क्रम में लगाइए।",
         "सही उत्तर है विकल्प B. क्रम है: आत्मीय सभा 1815 में, यूनिटेरियन कमेटी, वेदांत कॉलेज 1825 में, और ब्रह्म समाज 1828 में, जो उनका सबसे प्रसिद्ध सुधार आंदोलन था।"),
    90: ("प्रश्न 90. भारत के बहुआयामी गरीबी सूचकांक MPI के बारे में कौन से कथन सही हैं?",
         "सही उत्तर है विकल्प D. सभी कथन सही हैं। MPI तीन आयामों का उपयोग करता है: स्वास्थ्य, शिक्षा और जीवन स्तर। इसे NITI आयोग NFHS डेटा से प्रकाशित करता है। वैश्विक MPI UNDP और OPHI द्वारा जारी होता है।"),
    91: ("प्रश्न 91. वन हेल्थ दृष्टिकोण का क्या अर्थ है?",
         "सही उत्तर है विकल्प B. मानव, पशु और पर्यावरणीय स्वास्थ्य को जोड़कर महामारियों को रोकना। 70 प्रतिशत उभरते संक्रामक रोग पशुजनित हैं, इसलिए यह एकीकृत दृष्टिकोण महत्वपूर्ण है।"),
    92: ("प्रश्न 92. OIIPCRA के बारे में कौन सा कथन गलत है?",
         "सही उत्तर है विकल्प C. कथन 3 गलत है। OIIPCRA बड़े बांध निर्माण पर नहीं, बल्कि मौजूदा सिंचाई अवसंरचना के आधुनिकीकरण, सूक्ष्म सिंचाई और जलवायु-अनुकूल कृषि पर केंद्रित है।"),
    93: ("प्रश्न 93. बैदेहीशा बिलास के लेखक कौन हैं?",
         "सही उत्तर है विकल्प C. उपेंद्र भंज। वे 1670 से 1720 तक रहे और ओडिया साहित्य के सर्वश्रेष्ठ अलंकृत कवि यानी कवि सम्राट माने जाते हैं। वे दक्षिणी ओडिशा के भंज वंश से थे।"),
    94: ("प्रश्न 94. भारत में जैवमंडल आरक्षित क्षेत्रों के बारे में कौन सा कथन गलत है?",
         "सही उत्तर है विकल्प A. केवल कथन 3 गलत है। हिमालयी क्षेत्र में जैवमंडल आरक्षित हैं जैसे नंदा देवी, शीत मरुस्थल और कंचनजंगा।"),
    95: ("प्रश्न 95. मिशन कर्मयोगी का लक्ष्य क्या है?",
         "सही उत्तर है विकल्प B. सिविल सेवकों की क्षमता निर्माण और योग्यता विकास। 2020 में शुरू, यह iGOT प्लेटफॉर्म के माध्यम से सरकारी अधिकारियों के लिए योग्यता ढांचा बनाता है।"),
    96: ("प्रश्न 96. NBAP के तहत संकटग्रस्त प्रजाति पुनर्प्राप्ति कार्यक्रम किन प्रजातियों को लक्षित करता है?",
         "सही उत्तर है विकल्प C. सीमित भौगोलिक सीमा और घटती आबादी वाली प्रजातियां। ये विलुप्ति के सबसे अधिक जोखिम वाली प्रजातियां हैं जिन्हें लक्षित संरक्षण की आवश्यकता है।"),
    97: ("प्रश्न 97. किस मुगल सम्राट ने ओडिशा को अलग सूबा बनाया?",
         "सही उत्तर है विकल्प C. शाहजहां ने 1628 में। इससे पहले ओडिशा बंगाल सूबे का हिस्सा था। शाहजहां ने इसके प्रशासनिक महत्व को पहचानकर अलग सूबा बनाया।"),
    98: ("प्रश्न 98. अंतरराष्ट्रीय शिखर सम्मेलनों को उनके मेजबान शहरों से मिलाइए।",
         "सही उत्तर है विकल्प A. G7 2025 कैनानास्किस कनाडा में, NATO 2025 हेग नीदरलैंड में, SCO 2024 इस्लामाबाद पाकिस्तान में, और G20 2025 जोहान्सबर्ग दक्षिण अफ्रीका में।"),
    99: ("प्रश्न 99. अल नीनो घटना भारत पर क्या प्रभाव डालती है?",
         "सही उत्तर है विकल्प A. भारत में मानसून का कमज़ोर होना। अल नीनो वर्षों में हिंद महासागर और प्रशांत के बीच तापमान प्रवणता कमज़ोर होती है, जिससे मानसूनी वर्षा कम होती है। 1972, 1987, 2002 और 2009 के प्रमुख सूखे अल नीनो से जुड़े थे।"),
    100: ("प्रश्न 100. खो-खो विश्व कप 2025 के फाइनल में भारत ने किस देश को हराया?",
          "सही उत्तर है विकल्प C. नेपाल। भारत ने नई दिल्ली में आयोजित उद्घाटन खो-खो विश्व कप 2025 के पुरुष और महिला दोनों फाइनलों में नेपाल को हराया। बधाई, आपने सभी 100 प्रश्न पूरे कर लिए!")
}
